Builds a tiny PNG byte buffer in memory (just a valid signature and IHDR chunk, enough for the pilot's own header-only dimension reader), adds it to the presentation's image collection, places it on the slide as a PictureFrame, and checks the image's own pixel dimensions and the frame's on-slide size are both read back correctly.

Example:
// Authored example: add an in-memory image and a picture frame, then read the image's pixel dimensions back.
#include <cassert>
#include <cstdint>
#include <iostream>
#include <vector>

#include <Aspose/Slides/Foss/picture_frame.h>
#include <Aspose/Slides/Foss/pp_image.h>
#include <Aspose/Slides/Foss/presentation.h>
#include <Aspose/Slides/Foss/shape_collection.h>
#include <Aspose/Slides/Foss/shape_type.h>
#include <Aspose/Slides/Foss/slide.h>

using namespace Aspose::Slides::Foss;

namespace {
std::vector<std::uint8_t> minimal_png(std::uint32_t width, std::uint32_t height) {
    std::vector<std::uint8_t> bytes{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};
    auto push_be32 = [&bytes](std::uint32_t value) {
        bytes.push_back(static_cast<std::uint8_t>((value >> 24) & 0xFF));
        bytes.push_back(static_cast<std::uint8_t>((value >> 16) & 0xFF));
        bytes.push_back(static_cast<std::uint8_t>((value >> 8) & 0xFF));
        bytes.push_back(static_cast<std::uint8_t>(value & 0xFF));
    };
    push_be32(13);
    bytes.insert(bytes.end(), {'I', 'H', 'D', 'R'});
    push_be32(width);
    push_be32(height);
    bytes.insert(bytes.end(), {8, 2, 0, 0, 0});  // bit depth, color type, compression, filter, interlace
    push_be32(0);  // CRC placeholder; the pilot's own dimension reader never checks it
    return bytes;
}
}  // namespace

int main() {
    Presentation pres;
    auto png_bytes = minimal_png(64, 32);
    auto& image = pres.images().add_image(png_bytes);
    std::cout << "image size: " << image.width() << "x" << image.height() << '\n';
    assert(image.width() == 64);
    assert(image.height() == 32);

    auto& frame = pres.slides()[0].shapes().add_picture_frame(
        ShapeType::RECTANGLE, 40, 40, 160, 80, image);
    std::cout << "frame size: " << frame.width() << "x" << frame.height() << '\n';
    assert(frame.pp_image() == &image);
    assert(frame.width() == 160);
    assert(frame.height() == 80);
    assert(pres.images().size() == 1);
    return 0;
}
