Adds two rectangles and a straight connector, points the connector's start and end at each rectangle by a specific connection-site index, and checks that start_shape_connected_to/end_shape_connected_to and the two site-index accessors report back exactly what was set, while the connector itself still counts as a normal member of shapes().

Example:
// Authored example: connect two shapes with a connector and verify what it stores.
#include <cassert>
#include <iostream>

#include <Aspose/Slides/Foss/auto_shape.h>
#include <Aspose/Slides/Foss/connector.h>
#include <Aspose/Slides/Foss/presentation.h>
#include <Aspose/Slides/Foss/shape_collection.h>
#include <Aspose/Slides/Foss/shape_type.h>
#include <Aspose/Slides/Foss/slide.h>

using namespace Aspose::Slides::Foss;

int main() {
    Presentation pres;
    auto& shapes = pres.slides()[0].shapes();
    auto& box_a = shapes.add_auto_shape(ShapeType::RECTANGLE, 0, 0, 100, 60);
    auto& box_b = shapes.add_auto_shape(ShapeType::RECTANGLE, 300, 0, 100, 60);

    auto& connector = shapes.add_connector(ShapeType::STRAIGHT_CONNECTOR1, 100, 30, 200, 0);
    connector.set_start_shape_connected_to(&box_a);
    connector.set_start_shape_connection_site_index(3);
    connector.set_end_shape_connected_to(&box_b);
    connector.set_end_shape_connection_site_index(1);

    std::cout << "connected: " << (connector.start_shape_connected_to() == &box_a) << ' '
              << (connector.end_shape_connected_to() == &box_b) << '\n';

    assert(connector.start_shape_connected_to() == &box_a);
    assert(connector.end_shape_connected_to() == &box_b);
    assert(connector.start_shape_connection_site_index() == 3);
    assert(connector.end_shape_connection_site_index() == 1);
    assert(shapes.size() == 3);
    return 0;
}
