using namespace Aspose::Slides::Foss;

int main() {
    const std::string path = "authored_properties.pptx";

    {
        Presentation pres;
        auto& props = pres.document_properties();
        props.set_title("Quarterly Review");
        props.set_author("Dana Ops");
        props.set_subject("Q3 results");
        pres.save(path, SaveFormat::PPTX);
