Sets the title, author and subject core document properties on a new presentation, saves it to a temporary .pptx file, reloads it with the file-path constructor and checks all three properties read back exactly, before deleting the temporary file.

Example:
// Authored example: set document properties, save, reload, and read them back.
#include <cassert>
#include <filesystem>
#include <iostream>
#include <string>

#include <Aspose/Slides/Foss/document_properties.h>
#include <Aspose/Slides/Foss/export/save_format.h>
#include <Aspose/Slides/Foss/presentation.h>

using namespace Aspose::Slides::Foss;

int main() {
    const std::string path = "authored_properties.pptx";

    {
        Presentation pres;
        auto& props = pres.document_properties();
        props.set_title("Quarterly Review");
        props.set_author("Dana Ops");
        props.set_subject("Q3 results");
        pres.save(path, SaveFormat::PPTX);
    }

    Presentation reloaded(path);
    auto& props = reloaded.document_properties();
    std::cout << "title: " << props.title() << '\n';
    std::cout << "author: " << props.author() << '\n';
    std::cout << "subject: " << props.subject() << '\n';

    assert(props.title() == "Quarterly Review");
    assert(props.author() == "Dana Ops");
    assert(props.subject() == "Q3 results");

    std::filesystem::remove(path);
    return 0;
}
